def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * size]
    failure = [0]
    forbidden = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = index[ch]
            if children[node][c] == -1:
                children[node][c] = len(children)
                children.append([-1] * size)
                failure.append(0)
                forbidden.append(False)
            node = children[node][c]
        forbidden[node] = True

    queue = deque()
    for c in range(size):
        node = children[0][c]
        if node == -1:
            children[0][c] = 0
        else:
            queue.append(node)

    while queue:
        node = queue.popleft()
        forbidden[node] |= forbidden[failure[node]]
        for c in range(size):
            nxt = children[node][c]
            if nxt == -1:
                children[node][c] = children[failure[node]][c]
            else:
                failure[nxt] = children[failure[node]][c]
                queue.append(nxt)

    states = [i for i in range(len(children)) if not forbidden[i]]
    state_index = {node: i for i, node in enumerate(states)}
    count = len(states)

    matrix = [[0] * count for _ in range(count)]
    for i, node in enumerate(states):
        for nxt in children[node]:
            if not forbidden[nxt]:
                matrix[i][state_index[nxt]] += 1

    vector = [0] * count
    vector[state_index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, coefficient in enumerate(matrix[i]):
                        result[j] = (result[j] + value * coefficient) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, coefficient in enumerate(matrix[k]):
                            squared[i][j] = (
                                squared[i][j] + value * coefficient
                            ) % mod
            matrix = squared

    return sum(vector) % mod
